package main

// loginPage 登录页
const loginPage = `<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>API管理后台-登录</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: #f9fafb; display: flex; align-items: center; justify-content: center; min-height: 100vh; color: #111827; padding: 24px; }
        .login-card { background: #fff; border: 1px solid #e5e7eb; border-radius: 12px; box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06); padding: 48px 40px; width: 400px; max-width: 92vw; }
        .login-card h1 { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 26px; font-weight: 900; letter-spacing: -0.3px; color: #111827; text-align: center; margin-bottom: 36px; }
        .form-group { margin-bottom: 24px; } .form-group label { display: block; font-size: 13px; font-weight: 700; margin-bottom: 8px; }
        .form-group input { width: 100%; padding: 11px 12px; border: 1px solid #d1d5db; border-radius: 8px; background: #fff; color: #111827; font: 14px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; outline: none; transition: border-color 0.2s; }
        .form-group input:focus { border-color: #4f46e5; box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.12); }
        .btn-login { width: 100%; padding: 14px; background: #4f46e5; color: #fff; border: 0; border-radius: 8px; box-shadow: 0 2px 5px rgba(79, 70, 229, 0.25); font: 600 15px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; letter-spacing: -0.5px; cursor: pointer; transition: transform 0.2s, box-shadow 0.2s, background 0.2s, color 0.2s; -webkit-tap-highlight-color: transparent; }
        .btn-login:hover { background: #4338ca; box-shadow: 0 4px 10px rgba(67, 56, 202, 0.28); }
        .btn-login:focus, .btn-login:focus-visible, .btn-login:active { outline: none; box-shadow: none; }
        .error-msg { background: #fef2f2; border: 1px solid #fecaca; border-radius: 8px; color: #b91c1c; padding: 10px 12px; font-size: 13px; margin-bottom: 20px; display: none; } .error-msg.shake { animation: shake 0.4s ease; }
        @keyframes shake { 0%, 100% { transform: translateX(0); } 20% { transform: translateX(-6px); } 40% { transform: translateX(6px); } 60% { transform: translateX(-4px); } 80% { transform: translateX(4px); } }
        @media (max-width: 640px) { .login-card { box-shadow: 0 1px 5px rgba(0, 0, 0, 0.05); } .btn-login { box-shadow: 0 2px 5px rgba(79, 70, 229, 0.2); } }
    </style>
</head>
<body>
    <div class="login-card"><h1>API管理后台</h1><div class="error-msg" id="error">账号或密码错误</div><form id="loginForm" method="post" action="/login"><div class="form-group"><label for="username">账号</label><input type="text" id="username" name="username" autocomplete="username" required></div><div class="form-group"><label for="password">密码</label><input type="password" id="password" name="password" autocomplete="current-password" required></div><button type="submit" class="btn-login">登 录</button></form></div>
    <script>
        document.getElementById('loginForm').addEventListener('submit', function (e) { e.preventDefault(); var err = document.getElementById('error'); var u = document.getElementById('username').value.trim(); var p = document.getElementById('password').value; if (!u || !p) { showError('请输入账号和密码'); return; } err.style.display = 'none'; fetch('/login', { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: 'username=' + encodeURIComponent(u) + '&password=' + encodeURIComponent(p) }).then(function (resp) { return resp.json(); }).then(function (data) { if (data.success) { window.location.href = '/panel'; } else if (data.lockedUntil) { var remain = Math.ceil((data.lockedUntil * 1000 - Date.now()) / 1000); if (remain < 0) remain = 0; showError('尝试过于频繁，请 ' + remain + ' 秒后重试'); } else showError('账号或密码错误'); }).catch(function () { showError('网络错误，请重试'); }); });
        function showError(msg) { var err = document.getElementById('error'); err.textContent = msg; err.style.display = 'block'; err.classList.remove('shake'); void err.offsetWidth; err.classList.add('shake'); }
    </script>
</body>
</html>`

